(window.GO_WEB=window.GO_WEB||{})["pt-BR"]={"felles":{"_sprak":"Idioma","nav_browse":"Ver sorteios","nav_submit":"Envie um sorteio","nav_privacy":"Privacidade","hjem":"Início"},"index":{"_title":"GiveOwl – Sorteios e promoções em um só lugar","_desc":"O GiveOwl reúne sorteios, promoções e concursos para você participar, além de calendários do Advento online na temporada. Grátis, sem cadastro, e você sempre participa no site do organizador.","h1":"Encontre sorteios grátis e <em>calendários do Advento</em> online","lead":"Grátis e sem conta. Você sempre participa no site do organizador.","cta":"Ver sorteios","snart":"Em breve no","senere":"Depois na","h2_hva":"O que o GiveOwl faz","under_hva":"Uma lista organizada em vez de cem abas abertas.","k1_t":"Feito para o seu país","k1":"O GiveOwl escolhe seu país pelo aparelho. EUA, Reino Unido, Canadá, países nórdicos e cada vez mais. Dá para trocar quando quiser.","k2_t":"Sem compra","k2":"O filtro já vem ligado, então você só vê sorteios gratuitos. Prazo, prêmio e como participar num piscar de olhos.","k3_t":"Calendários do Advento na temporada","k3":"Em novembro e dezembro, os calendários do Advento online ganham uma aba própria, com as portinhas de hoje dos seus favoritos.","trygg_t":"Nós só indicamos o link. Você participa no site do organizador.","trygg":"O GiveOwl nunca coleta suas participações, não pede cadastro e não cobra nada. Sempre leia o regulamento oficial no site do organizador antes de participar.","h2_arr":"Vai fazer um sorteio?","under_arr":"Conte para a gente. Entrar na lista é grátis.","cta_arr":"Envie um sorteio","fot":"O GiveOwl não tem vínculo com os organizadores listados. © 2026 HENDT AS, Noruega.","fot_aff":"Itens marcados como “Anúncio” ou “Patrocinado” são espaços pagos ou links de afiliado. Se você participar ou comprar por eles, podemos receber uma comissão sem custo extra para você. Isso nunca decide quais sorteios entram na lista. <a href=\"/privacy/#ads\">Saiba mais</a>"},"submit":{"_title":"Envie um sorteio – GiveOwl","h1":"Envie um sorteio","lead":"Vai fazer um sorteio, promoção ou calendário do Advento online? Conte para a gente. Entrar na lista é grátis, e revisamos cada envio antes de publicar.","f_arr":"Organizador / marca *","f_tittel":"Nome do sorteio *","f_premie":"Prêmio(s) *","p_premie":"ex.: vale-presente de R$ 500, 3 ganhadores","f_type":"Tipo","o_konk":"Sorteio / promoção / concurso","o_jul":"Calendário do Advento online","f_land":"Aberto a moradores de *","o_int":"Mundo todo","f_start":"Data de início","f_slutt":"Data final / prazo *","f_url":"Link do sorteio ou do regulamento oficial (seu próprio site) *","f_delta":"Como participar","p_delta":"ex.: Preencha o formulário uma vez por dia. Maiores de 18 anos.","f_kjop":"Sem compra (existe uma forma gratuita de participar)","f_epost":"Seu e-mail (para respondermos) *","f_ok":"Sou o organizador ou tenho permissão para enviar, e as informações estão corretas.","send":"Enviar por e-mail","kopier":"Copiar dados","ft_t":"Destaque seu sorteio","ft_lead":"Quer mais participantes? Itens patrocinados aparecem perto do topo da lista (no máximo dois por vez) e são sempre marcados como “Patrocinado”. Itens normais continuam grátis.","ft_1":"Destaque perto do topo nos países que você escolher","ft_2":"Marcado claramente como “Patrocinado”, de acordo com as regras de publicidade","ft_3":"As mesmas regras de qualidade de qualquer item: organizador real, regulamento oficial, sem pegadinhas pagas","ft_pris_t":"Preço:","ft_pris":"preço de lançamento a partir de 29 USD / 25 EUR / 290 NOK por semana. Itens normais continuam grátis.","ft_se":"Ver preços e como reservar","ft_cta":"Fale com info@hendtas.com","merk":"Esta página não salva nada. “Enviar por e-mail” abre seu próprio app de e-mail com os dados preenchidos. Veja nossa <a href=\"/privacy/\">política de privacidade</a>.","mangler":"Preencha os campos obrigatórios (*).","kopiert":"Copiado. Cole em um e-mail para ","aapner":"Abrindo seu app de e-mail…"},"privacy":{"_title":"GiveOwl – Política de privacidade","_html":"<div class=\"card binding\"><b>Esta é uma tradução para sua conveniência. Somente a versão em inglês é vinculante; em caso de divergência, vale o inglês.</b> <a href=\"#en\">English</a></div>\n<h1>Política de privacidade do GiveOwl</h1>\n<p class=\"meta\">Última atualização: 17 de outubro de 2026 · Vale para os apps GiveOwl para Android e iPhone (<code>com.hendtas.giveowl</code>) e para o site giveowl.com</p>\n<div class=\"card\"><b>Resumindo:</b> O GiveOwl é um diretório de sorteios, promoções, concursos e calendários do Advento online. Não há contas de usuário, anúncios, compras nem ferramentas de análise. Seus favoritos e ajustes ficam salvos só no seu aparelho. Quando você participa de um sorteio, faz isso no site do próprio organizador. O que você envia lá vai para o organizador, não para nós. Não vendemos nem compartilhamos dados pessoais.</div>\n<h2>1. Quem é o responsável?</h2>\n<p>O controlador é a HENDT AS, Noruega. E-mail: <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a>.</p>\n<h2>2. O que fica salvo no seu aparelho</h2>\n<p>O seguinte fica salvo localmente no app (ou no seu navegador em giveowl.com). Não temos acesso e nada disso é enviado para nós:</p>\n<ul><li>quais sorteios e calendários você marcou como favoritos;</li><li>em quais sorteios você marcou participação (“Minhas participações” e “Hoje”) e em quais dias, para as sequências e a grade do calendário do Advento;</li><li>seus ajustes: idioma, país, filtros e ordenação (por exemplo “Sem compra”) e os ajustes de lembretes;</li><li>uma cópia da última lista baixada pelo app, para funcionar offline.</li></ul>\n<p>Seu idioma e país são escolhidos a partir dos ajustes do aparelho na primeira vez que você abre o GiveOwl. Isso acontece no aparelho; não usamos sua localização. Se o backup automático do Android estiver ativado, ele pode incluir dados do app no backup da sua conta Google. Você pode apagar todos os dados desinstalando o app, usando “Limpar armazenamento” nas configurações do Android ou limpando os dados do site no navegador. No iPhone, os dados do app podem ser incluídos no seu backup do iCloud ou do aparelho, se você o ativou. Você pode apagar todos os dados excluindo o app.</p>\n<p>O GiveOwl não tem login, anúncios, compras no app, ferramentas de análise, cookies de rastreamento nem relatórios de falhas. O app não pede acesso à sua localização, contatos, câmera, microfone ou arquivos.</p>\n<h3>Lembretes</h3>\n<p>Se você ativar os lembretes, o app pede permissão ao Android para mostrar notificações. Os lembretes (por exemplo, um dia antes de um sorteio favorito encerrar) são agendados localmente no aparelho pelo Android. Nenhum dado de lembrete é enviado para nós nem para serviços de push, e você pode desativá-los a qualquer momento no app ou nas configurações do Android. No iPhone, o app pede permissão ao iOS da mesma forma, e os lembretes são agendados localmente pelo iOS. Você pode desativá-los no app ou nos Ajustes do iOS.</p>\n<h3>Compartilhar</h3>\n<p>Ao tocar em “Compartilhar”, abre-se o menu de compartilhamento do Android com um link para o sorteio em giveowl.com. Você escolhe com qual app compartilhar, e vale a política de privacidade desse app. Nada é enviado para nós. No iPhone, abre-se da mesma forma o menu de compartilhamento do iOS.</p>\n<h3>Avaliar o app</h3>\n<p>Depois que você usar o app para Android por um tempo, ele pode pedir ao Google Play para mostrar a janela de avaliação do Google (no máximo uma vez a cada 90 dias). Se você deixar uma nota ou um comentário, ele é enviado ao Google Play e tratado de acordo com os termos e a política de privacidade do Google, como um comentário escrito na Play Store. O GiveOwl não recebe nenhuma informação dessa janela, nem mesmo se você avaliou. No iPhone, o app pode pedir ao iOS que mostre a janela de avaliação da Apple (a Apple a mostra no máximo três vezes por ano). A avaliação é enviada à Apple e tratada conforme os termos da Apple; o GiveOwl não recebe nada.</p>\n<h2>3. Atualização da lista</h2>\n<p>Para mostrar sorteios novos, o app baixa uma lista atualizada de <code>https://giveowl.com/data.json</code>. A solicitação não contém informações sobre você, mas, como em qualquer acesso à web, o servidor vê seu endereço IP e dados técnicos, como o tipo de aparelho ou navegador. O serviço que hospeda o site e a lista, GitHub Pages (GitHub, Inc.), pode guardar esses dados em registros técnicos de curta duração conforme suas próprias políticas. Não usamos esses dados para identificar você.</p>\n<p>Se você ativar as notificações de “Novidades” no app para Android, o Android baixa a mesma lista em segundo plano cerca de duas vezes por dia, só quando você está on-line. O app a compara no seu aparelho com os itens que você já viu e mostra uma única notificação se houver algo novo. A lista de itens vistos fica no seu aparelho, e a solicitação é a mesma descrita acima: não contém informações sobre você. Você pode desativar isso a qualquer momento nas configurações do app. No iPhone, é o iOS que decide quando o download em segundo plano acontece (Atualização em Segundo Plano). Se o giveowl.com não estiver acessível, o app baixa o mesmo arquivo público do GitHub (raw.githubusercontent.com); essa solicitação também não contém informações sobre você.</p>\n<h2>4. Envio de sorteios</h2>\n<p>A página “Envie um sorteio” em giveowl.com não salva nada. Ela prepara um e-mail no seu próprio app de e-mail. Se você enviar, recebemos os dados que você escreveu e seu endereço de e-mail, e os usamos apenas para revisar o sorteio e responder. Apagamos o e-mail quando ele não for mais necessário, normalmente em até 12 meses.</p>\n<h2>5. Links para organizadores</h2>\n<p>O GiveOwl apenas indica links. Quando você toca em “Participar no site”, o site do organizador abre no navegador, e valem o regulamento oficial e a política de privacidade do organizador. Não somos responsáveis pelos sorteios, prêmios ou pelo tratamento de dados dos organizadores. Itens pagos são marcados como “Patrocinado” e links de afiliado como “Anúncio” (veja a seção 5a).</p>\n<h2 id=\"tr-ads\">5a. Itens patrocinados, links de afiliado e anúncios</h2>\n<p>O GiveOwl pode mostrar itens patrocinados (marcados como “Patrocinado”) e links de afiliado (marcados como “Anúncio”). Com um link de afiliado, o organizador ou uma rede de afiliados pode nos pagar uma comissão se você participar ou comprar algo depois de seguir o link. Isso não custa nada a mais para você. Pagamentos nunca decidem quais sorteios listamos ou como os descrevemos, e só listamos sorteios que seguem nossas regras de qualidade.</p>\n<p>Quando você abre um link desses, ele abre no navegador, e a rede de afiliados ou o organizador podem usar cookies ou tecnologias semelhantes no próprio site para registrar que você veio do GiveOwl. Isso acontece segundo a política de privacidade deles, não no app GiveOwl. O app em si não rastreia você.</p>\n<p>Hoje o GiveOwl não mostra anúncios no app. Se adicionarmos anúncios no futuro, atualizaremos antes esta política e as informações de segurança dos dados do app.</p>\n<h2>6. Crianças</h2>\n<p>O GiveOwl é destinado a adultos com 18 anos ou mais, porque a maioria dos sorteios só aceita participantes maiores de 18 anos (alguns exigem 21+), conforme o regulamento do organizador. O GiveOwl não é direcionado a crianças. Não coletamos intencionalmente dados pessoais de crianças, e o app não coleta dados pessoais de ninguém.</p>\n<h2>7. Seus direitos</h2>\n<p>Dependendo de onde você mora (por exemplo, pelo GDPR no EEE e no Reino Unido, pela LGPD no Brasil ou por leis estaduais dos EUA como a CCPA/CPRA), você pode ter direito de acessar, corrigir, excluir ou restringir o tratamento dos seus dados pessoais, à portabilidade, de se opor e de recusar a venda ou o compartilhamento de dados pessoais. Não vendemos nem compartilhamos dados pessoais e não temos contas de usuário, então normalmente não conseguimos associar dados a você. Fale com a gente em <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a> e ajudaremos. Você não será discriminado por exercer seus direitos. No EEE, você também pode reclamar à autoridade norueguesa de proteção de dados (Datatilsynet, <a href=\"https://www.datatilsynet.no/en/\">datatilsynet.no</a>) ou à autoridade local.</p>\n<h2>8. Alterações</h2>\n<p>Atualizamos esta política quando o GiveOwl muda, por exemplo quando adicionamos recursos ou fornecedores. A data no topo indica a versão atual.</p>\n<h2>9. Contato</h2>\n<p>HENDT AS · Noruega · <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a></p>\n"},"seo":{"g_h1":"Sorteios e promoções em {land}","g_title":"Sorteios e promoções em {land} ({m}) – GiveOwl","g_desc":"{n} sorteios e promoções abertos a moradores de {land}, verificados em {d}. Com prazo, prêmio e como participar no site do organizador.","a_h1":"Calendários do Advento online em {land} {y}","a_title":"Calendários do Advento online {y} em {land} – GiveOwl","a_desc":"{n} calendários do Advento online em {land} para {y}: datas, prêmios e como participar.","a_all_h1":"Calendários do Advento online {y}","a_all_desc":"Calendários do Advento online de {y} em vários países, com prêmios e como participar no site do organizador.","intro":"Cada sorteio leva ao regulamento oficial do organizador. O GiveOwl nunca coleta suas participações.","open":"Aberto","ended":"Encerrado","coming":"Em breve","deadline":"Prazo","prize":"Prêmio","how":"Como participar","enter":"Participar no site do organizador","app":"Lembretes e lista diária no app GiveOwl: em breve no Google Play.","browse":"Abrir a lista completa com filtros","other":"Outros países","ended_note":"Este sorteio foi encerrado. Veja os sorteios abertos em {land}.","nopurchase":"Sem compra","purchase":"Exige compra","updated":"Atualizado em {d}","worldwide":"Mundo todo","rules":"Regulamento oficial","org_lang":"O prêmio e as instruções aparecem no idioma do organizador.","bycountry":"Explorar por país","expected":"Previsto – ainda não confirmado para 2026","f_end_h1":"Sorteios que terminam em breve: {land}","f_end_desc":"{n} sorteios ({land}) que encerram em 7 dias. Última chance – verificado em {d}.","f_new_h1":"Novos sorteios desta semana: {land}","f_new_desc":"{n} sorteios ({land}) adicionados nos últimos 7 dias.","f_daily_h1":"Sorteios com participação diária: {land}","f_daily_desc":"{n} sorteios ({land}) para participar todos os dias.","f_lists":"Mais listas","f_rss":"Feed RSS"}};
